INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-trump-iran-strikes-new-year', 'trump-inclined-resume-iran-strikes-after-new-year-missile-drone-surge-claim', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Trump says he is inclined to resume strikes on Iran after the new year if no deal is reached', 'On Sunday, Nov. 22, the president also claimed Iran fired more missiles and drones in the past week than at any point in more than a year, and he tied the rise to Democrats'' midterm wins.', 'President Trump said on Sunday, Nov. 22, that he is inclined to resume U.S. strikes on Iran after the new year if indirect talks do not produce a deal, according to reporting by JNS and Fox News. He gave no specific deadline.

## The claim about a surge

In a Truth Social post on Sunday, Trump wrote that Iran had launched more missiles and drones over the past week than at any time in more than a year, and that U.S. forces shot all of them down without damage, Fox News reported. Neither outlet could independently verify the claim.

Trump linked the increase to the Nov. 3 midterm elections, in which Democrats won control of both chambers of Congress. He said he had predicted that Iran would become more aggressive if Democrats won.

## Talks and the blockade

Trump told Fox News that Iran''s negotiators talk constantly without producing results, JNS reported. A day earlier, on Saturday, Nov. 21, he said he wants a permanent agreement guaranteeing that Iran never obtains a nuclear weapon.

Fox News reported that Trump also warned that Iranian vessels testing the U.S. naval blockade would be sunk.

## Context

JNS noted a CBS News report, citing sources on Friday, Nov. 20, that the United States and Israel are weighing a new military offensive against Iran. On Nov. 19, Trump told Israel''s Channel 12 he was not rushing a decision.

Adm. Brad Cooper, head of U.S. Central Command, ended a weeklong trip to Israel, Qatar and Saudi Arabia on Sunday, Nov. 22, and met some of the roughly 50,000 U.S. troops in the region, according to JNS.

In Washington, the Senate rejected a war powers resolution on Iran by 48-51 on Thursday, Nov. 19, Fox News reported. Democrats who take control of Congress in January have said they want to end the war.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/US_Navy_101123-N-6003P-299_The_aircraft_carrier_USS_Harry_S._Truman_(CVN_75)_operates_in_the_Arabian_Sea_in_support_of_Operation_Enduring_Freedom.jpg/1280px-US_Navy_101123-N-6003P-299_The_aircraft_carrier_USS_Harry_S._Truman_(CVN_75)_operates_in_the_Arabian_Sea_in_support_of_Operation_Enduring_Freedom.jpg', 'The aircraft carrier USS Harry S. Truman in the Arabian Sea, 2010 (file photo). U.S. Navy photo (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-23.sql', 9, 1, 'newsroom-assistant', '2026-11-23T11:00:00.000Z', '2026-11-23T11:00:00.000Z');
