INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-jeffries-face-the-nation-agenda', 'jeffries-face-the-nation-democratic-agenda-iran-war-health-care-stock-trading-ban', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Jeffries lays out House Democrats'' first goals: ending the Iran war, lowering costs and banning stock trading by lawmakers', 'Speaking on CBS''s Face the Nation on Sunday, Nov. 22, the speaker-designate said impeachment is neither ruled in nor ruled out and that investigations will follow the facts.', 'Rep. Hakeem Jeffries of New York, whom House Democrats have nominated to be speaker when their majority takes over in January, used an interview on CBS''s Face the Nation on Sunday, Nov. 22, to describe what the new majority will try to do first.

## Iran and prices

Jeffries said Democrats want to end what he called a reckless and costly war of choice in Iran. He argued the war has pushed up the price of gasoline, food and diesel. "Life is way too expensive," he said.

## Early bills

He said early priorities include reversing Medicaid cuts, restoring SNAP food aid, addressing tariffs and extending Affordable Care Act tax credits. He would not predict whether President Trump would sign those bills.

Jeffries said House Democrats plan an early vote on banning members of Congress from trading stocks. On health care, he also mentioned lowering the Medicare eligibility age, adding vision, hearing and dental coverage and covering children.

## Investigations

Asked about impeachment, Jeffries said nothing is ruled in or ruled out and that the House''s investigations will follow the facts, according to the CBS News transcript.

The new Congress, the 120th, begins on Jan. 3, 2027.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Flickr_-_USCapitol_-_Apotheosis_of_Democracy_-_House_Pediment.jpg/1280px-Flickr_-_USCapitol_-_Apotheosis_of_Democracy_-_House_Pediment.jpg', '"Apotheosis of Democracy," the pediment over the House wing of the U.S. Capitol (file photo). Architect of the Capitol (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-23.sql', 8, 0, 'newsroom-assistant', '2026-11-23T11:00:00.000Z', '2026-11-23T11:00:00.000Z');
