INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261123-jeffries-face-the-nation-agenda-ev1', 'bd-20261123-jeffries-face-the-nation-agenda', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-23T11:00:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-dec-11-funding-deadline', 'congress-thanksgiving-break-december-11-government-funding-deadline-continuing-resolution', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Congress breaks for Thanksgiving with a Dec. 11 funding deadline and most spending bills unfinished', 'Appropriators in both parties say a stopgap bill is likely, but Democrats say they will not fund defense spending for the Iran war.', 'Lawmakers leave Washington for the Thanksgiving recess, scheduled for Nov. 23 to Nov. 27, with federal funding set to run out on Friday, Dec. 11, and no deal in place.

## Where the bills stand

Of the 12 annual appropriations bills, the House had passed three and the Senate none as of the week ending Nov. 21, the Deseret News reported. The Senate released its final batch of bills that week.

Rep. Mike Simpson, an Idaho Republican, told the Deseret News that a continuing resolution will be needed because the full-year bills will not be done by Dec. 11, and that the open question is how long a stopgap should last. House Appropriations Chairman Tom Cole of Oklahoma said in a statement that giving up on full-year bills in this Congress would be a disservice to the public.

Rep. Rosa DeLauro of Connecticut, the top Democrat on the committee, said she did not think anyone wants a shutdown. She added that "a shutdown doesn''t stop the war," a reference to Democrats'' refusal to fund defense spending for the war with Iran.

## The calendar

According to a lame-duck calendar compiled by Quorum, the Senate is aiming to adjourn by Dec. 18 and the House''s last scheduled day is Dec. 17. Federal surface transportation programs also expire on Dec. 11.

Democrats, who won both chambers on Nov. 3, take control when the 120th Congress convenes on Jan. 3, 2027.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Flickr_-_USCapitol_-_Fall_Foliage_at_the_U.S._Capitol.jpg/1280px-Flickr_-_USCapitol_-_Fall_Foliage_at_the_U.S._Capitol.jpg', 'Fall foliage at the U.S. Capitol (file photo). Architect of the Capitol (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-23.sql', 8, 0, 'newsroom-assistant', '2026-11-23T11:00:00.000Z', '2026-11-23T11:00:00.000Z');
