INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-bessent-nvidia-chip-probe', 'bessent-face-the-nation-nvidia-chip-sales-china-megaspeed-data-centers-microsoft-outage', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'Bessent says the administration needs answers from Nvidia about chip sales to China', 'On Face the Nation on Sunday, Nov. 22, the Treasury secretary also blamed Democrats'' stance on AI data centers for unsettling investors, and Microsoft''s Brad Smith explained a recent outage.', 'Treasury Secretary Scott Bessent said on CBS''s Face the Nation on Sunday, Nov. 22, that the administration wants Nvidia''s interim leadership to explain whether a "culture of noncompliance" existed around the company''s chip sales to China.

## The chip inquiry

Bessent said a company called Megaspeed may have served as a front in Singapore, and that Treasury and other departments pushed to put it on a U.S. blacklist. He said a new rule covering remote access to advanced chips was adopted the week before, and that Nvidia''s board is moving very quickly. "We do need answers," he said.

## Data centers and markets

Bessent argued that Democrats'' push to slow the build-out of AI data centers rattled investors and contributed to the recent stock market sell-off. He also said the AI industry has done a poor job of explaining itself to the public.

The program aired a clip of President Trump saying the United States will not allow data centers to be built in other countries. Bessent said he had not discussed that idea with the president. Microsoft President Brad Smith said most data centers support cloud services that must sit near their customers, so any such policy would need nuance.

## The Microsoft outage

Smith said a recent Microsoft outage was caused by software updated four months earlier interacting with a new update and a shift in network traffic. He said it was not caused by AI or a cyberattack, that Microsoft has taken nine corrective steps and that it plans 13 more. Bessent said the banking system is safe.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Aerial_view_of_U.S._Treasury_Department_building,_Washington,_D.C_LCCN2011634194.tif/lossy-page1-1280px-Aerial_view_of_U.S._Treasury_Department_building,_Washington,_D.C_LCCN2011634194.tif.jpg', 'Aerial view of the U.S. Treasury Department building, Washington (file photo). Carol M. Highsmith Archive, Library of Congress, no known restrictions, via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-23.sql', 7, 0, 'newsroom-assistant', '2026-11-23T11:00:00.000Z', '2026-11-23T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261123-bessent-nvidia-chip-probe-src1', 'bd-20261123-bessent-nvidia-chip-probe', 'Full transcript of "Face the Nation with Margaret Brennan," Nov. 22, 2026', 'https://www.cbsnews.com/news/full-transcript-of-face-the-nation-with-margaret-brennan-nov-22-2026/', 'CBS News', 'web', 'PRIMARY_SOURCE', 1, 1, '2026-11-23T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-23. Editor to confirm.', 'newsroom-assistant', '2026-11-23T11:00:00.000Z');
