INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-rochon-dhs-ads-ruling', 'judge-rochon-declines-long-term-ban-trump-administration-taxpayer-funded-dhs-ads', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Federal judge in New York declines a long-term ban on the Trump administration''s taxpayer-funded TV ads', 'U.S. District Judge Jennifer L. Rochon said the challengers had not shown ongoing harm now that the Nov. 3 midterms are over. A similar Democratic suit is pending in Washington.', 'A federal judge in New York has refused to issue a long-term order blocking television ads that the Trump administration paid for with public money, the Associated Press reported on Friday, Nov. 20.

## The ruling

U.S. District Judge Jennifer L. Rochon said the challengers, a coalition that includes the watchdog group Common Cause, had not shown the ads were still causing imminent and irreparable harm after the Nov. 3 midterm elections. "Those elections have now passed," she wrote, according to the AP. The coalition is represented by the legal group Democracy Forward.

## The ads

The administration began airing the spots in September. They were paid for at least in part through a $20 million Department of Homeland Security contract, the AP reported. They include highlight reels, mentions of tax cuts and law enforcement, and a reworked clip from the 2024 campaign. Some also ran on White House social media accounts and its website.

The White House has described the spots as public service announcements. It did not respond to the AP''s request for comment.

## The other case

In Washington, D.C., the Democratic National Committee is seeking a preliminary injunction against the ads. The judge there had not ruled after a hearing held during the week of Nov. 16, and a temporary restraining order in that case was set to expire soon, according to the AP.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Courthouses_on_Foley_Square.jpg/1280px-Courthouses_on_Foley_Square.jpg', 'Federal courthouses on Foley Square, Manhattan (file photo). Jim Henderson via Wikimedia Commons; editor to confirm the public-domain release on the file page', 'public_domain', 'newsroom', 'content/2026-11-23.sql', 7, 0, 'newsroom-assistant', '2026-11-23T11:00:00.000Z', '2026-11-23T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261123-rochon-dhs-ads-ruling-src1', 'bd-20261123-rochon-dhs-ads-ruling', 'US judge declines long-term ban on Trump admin''s taxpayer-funded ads (Associated Press)', 'https://www.business-standard.com/world-news/us-judge-declines-long-term-ban-on-trump-admin-s-taxpayer-funded-ads-126112100092_1.html', 'Associated Press via Business Standard', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-23T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-23. Editor to confirm.', 'newsroom-assistant', '2026-11-23T11:00:00.000Z');
