INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-celtics-warriors-kings-losses', 'celtics-lose-warriors-88-87-kings-97-96-four-game-losing-streak-tatum', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Celtics lose 88-87 at Golden State, a night after a 97-96 loss at Sacramento, for a fourth straight defeat', 'Jayson Tatum scored 27 points on Sunday, Nov. 22, but missed the final shot over Draymond Green. On Saturday, Keegan Murray''s putback with 5 seconds left beat Boston.', 'The Boston Celtics finished a West Coast back-to-back with two one-point losses, and have now lost four games in a row. They are 11-6.

## Sunday, Nov. 22: Warriors 88, Celtics 87

At Chase Center in San Francisco, Boston led 75-69 after three quarters but scored only 12 points in the fourth.

Jayson Tatum had 27 points, 10 rebounds and six assists, according to recaps from Yardbarker and SB Nation, but did not make a field goal in the second half. Derrick White scored 14 points on 6-of-21 shooting. Paul George rested on the second night of the back-to-back.

In the final two minutes, a Brandin Podziemski three-pointer was wiped out when a Boston challenge turned the play into an offensive foul. Tatum then made one of two free throws, and with the Celtics trailing by one, his last shot, contested by Draymond Green, missed.

Podziemski led Golden State with 18 points and seven rebounds. Gui Santos and Charles Bassey each scored 13. The Warriors, playing without Stephen Curry (oblique strain), ended a five-game losing streak and improved to 9-8.

## Saturday, Nov. 21: Kings 97, Celtics 96

At Golden 1 Center in Sacramento, Payton Pritchard''s step-back gave Boston a 96-95 lead with 11.8 seconds left, but Keegan Murray won it with a putback over three defenders with 5 seconds to play, ESPN reported. Murray finished with 15 points and 12 rebounds.

Boston led 54-41 at halftime before the Kings won the third quarter 35-13. The Celtics missed all 13 of their three-point attempts in that quarter and shot 22% on 58 threes for the game. George scored 19. Tatum (rest), White (shoulder) and Mitchell Robinson (illness) did not play. The Kings, now 2-14, ended an eight-game losing streak.

## Next

The Celtics visit the Washington Wizards on Tuesday, Nov. 24, at 8 p.m. ET.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ac/US_Navy_111110-N-DR144-327_The_University_of_North_Carolina_basketball_team_practices_in_the_basketball_arena_on_the_flight_deck_aboard_the_Nimitz.jpg/1280px-US_Navy_111110-N-DR144-327_The_University_of_North_Carolina_basketball_team_practices_in_the_basketball_arena_on_the_flight_deck_aboard_the_Nimitz.jpg', 'A basketball court on the flight deck of USS Carl Vinson for the 2011 Carrier Classic (file photo, not from this game). U.S. Navy photo (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-23.sql', 8, 0, 'newsroom-assistant', '2026-11-23T11:00:00.000Z', '2026-11-23T11:00:00.000Z');
