INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261123-yale-harvard-bc-syracuse', 'yale-beats-harvard-20-17-fenway-park-boston-college-beats-syracuse-27-15', 'newsroom', 'news_story', 'college-football', 'EDITORIAL_REVIEW', 0, 'Yale edges Harvard 20-17 at Fenway Park; Boston College beats Syracuse 27-15 on Senior Day', 'Yale scored the winning touchdown with 3:37 left in the 142nd playing of The Game on Saturday, Nov. 21. In Chestnut Hill, Bo MacCormack III ran for 236 yards.', '## Yale 20, Harvard 17

Yale beat No. 17 Harvard 20-17 on Saturday, Nov. 21, in the 142nd playing of The Game, held at Fenway Park in Boston, Harvard Athletics reported.

Yale''s Damien Henderson returned an interception 28 yards for a touchdown on Harvard''s opening possession, and Yale led 13-10 at halftime. DJ Gordon''s 6-yard touchdown run put Harvard ahead 17-13 with 11:46 to play. Yale answered with a 75-yard drive that ended in Dante Reno''s 2-yard touchdown pass to Graham Smith with 3:37 left. Harvard''s last two drives ended on downs and with an interception.

Gordon ran for 115 yards on 13 carries. Harvard outgained Yale 367 yards to 281 but committed four turnovers to Yale''s one. Harvard finished the regular season 8-2 and 5-2 in the Ivy League; Yale is 6-4 and 4-3.

## Boston College 27, Syracuse 15

At Alumni Stadium in Chestnut Hill, Boston College beat Syracuse 27-15 on Senior Day before 35,109 fans, ESPN and the Associated Press reported.

Bo MacCormack III, a former Syracuse commit, carried 30 times for 236 yards, including a 56-yard touchdown run in the third quarter. Quarterback Mason McKenzie completed 14 of 24 passes for 131 yards and touchdowns to Zeke Moore and Nedrick Boldin Jr. Luca Lombardo kicked field goals of 46 and 32 yards.

Syracuse quarterback Steve Angeli left with an injury; backup Malachi Nelson threw for 202 yards and a touchdown. The Orange reached the red zone four times but came away with only two field goals.

BC ended a three-game losing streak and improved to 5-6. The AP said the Eagles can still become bowl-eligible, but only with an upset at No. 5 Miami on Saturday, Nov. 28. Syracuse fell to 5-6, ending its bowl hopes.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Tigers_at_Bulldogs_football_game_1915-11-13.JPG/1280px-Tigers_at_Bulldogs_football_game_1915-11-13.JPG', 'Princeton at Yale football game, Nov. 13, 1915 (historic file photo, public domain by age). Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-23.sql', 7, 0, 'newsroom-assistant', '2026-11-23T11:00:00.000Z', '2026-11-23T11:00:00.000Z');
